        "e": "n(monomer CH₂=CHCl) = 10⁶/62,5 = 16000 mol. Cần 2 mol CH₄ cho 1 mol monomer (theo stoichiometry) → n(CH₄ cần lý thuyết) = 32000 mol. H = 20% → n(CH₄ thực tế) = 32000/0,2 = 160000 mol. V(CH₄) = 160000 × 24,79 = 3,9664×10⁶ L = 3966,4 m³. Khí thiên nhiên 80% CH₄ → V = 3966,4/0,8 ≈ 4958 m³.",
        "u": "m³",
        "tol": "5",
        "ac": "4958.0|4957.5|4960|4959"
