        "q": "Khi dùng biogas (giả sử chỉ chứa CH₄, ΔH = –890 kJ/mol) để thay khí gas (40% C₃H₈ ΔH=–2220 kJ/mol và 60% C₄H₁₀ ΔH=–2850 kJ/mol theo thể tích), với cùng năng lượng cần dùng thì lượng CO₂ thải ra giảm bao nhiêu %?",
