        "a": "47",
        "e": "Gọi n(C₃H₈) = x, n(C₄H₁₀) = 2x. m = 44x + 116x = 160x = 12000 → x = 75 mol. Q = 75×2220 + 150×2874 = 597600 kJ. Hữu ích = 597600 × 0,8 = 478080 kJ. Số ngày = 478080/10000 ≈ 47,8 → 47 ngày trọn.",
