        "q": "Cho các ester: C2H5COOCH3 (1); CH3CH2CH2COOC2H5 (2); CH3COOCH3 (3); C2H5COOC2H5 (4).\nb. Ester (2) và (4) có mùi dứa chín.",
        "o": "",
