        "q": "Cho các ester: C2H5COOCH3 (1); CH3CH2CH2COOC2H5 (2); CH3COOCH3 (3); C2H5COOC2H5 (4).\nc. Độ tan trong nước giảm dần theo thứ tự: (2) > (1) > (3) > (4).",
