        "q": "Cho các ester: HCOOCH3; CH3COOCH3; (COOCH3)2; (HCOO)2C2H4; CH2=CHCOOCH3; C2H5COOC2H5; CH3COOC6H5. Có bao nhiêu ester no, đơn chức, mạch hở?",
