        "q": "(Đề MH – 2020) Hỗn hợp X gồm hai ester C8H8O2 chứa vòng benzene. Để phản ứng hết 0,25 mol X cần tối đa 0,35 mol NaOH, thu được m gam hỗn hợp hai muối. Tính m?",
