        "ch": "g12c2",
        "q": "(Đề THPT QG - 2019) Đun nóng 100 mL dung dịch glucose a mol/L với lượng dư dung dịch AgNO3 trong NH3. Sau khi phản ứng hoàn toàn thu được 21,6 gam kết tủa. Tính giá trị của a?",
        "o": "",
