          "q": "(SGK Hóa học 12 CB) Cho các phát biểu: (a) Xà phòng là sản phẩm của phản ứng xà phòng hóa chất béo với NaOH hoặc KOH; (b) Muối sodium/potassium của acid hữu cơ là thành phần chính của xà phòng; (c) Đun nóng chất béo với NaOH hoặc KOH ta được xà phòng; (d) Từ dầu mỏ sản xuất được chất giặt rửa tổng hợp. Số phát biểu đúng là",
