          "q": "(Đề THPT QG - 2016) Cho các phát biểu: (a) Glucose được gọi là đường nho. (b) Chất béo là diester của glycerol với acid béo. (c) Phân tử amylopectin có cấu trúc mạch phân nhánh. (d) Ở nhiệt độ thường, triolein ở trạng thái rắn. (e) Trong mật ong chứa nhiều fructose. (f) Tinh bột là lương thực cơ bản. Số phát biểu đúng là",
