          "q": "(Đề TSCĐ - 2011) Cho các chất: saccharose, glucose, fructose, ethyl formate, formic acid và aldehyde acetic. Số chất vừa tráng bạc vừa phản ứng với Cu(OH)2 ở điều kiện thường là bao nhiêu?",
