          "q": "Câu 14: Tiến hành thí nghiệm phản ứng xà phòng hóa theo các bước sau đây:\nBước 1: Cho vào bát sứ khoảng 1 gam mỡ (hoặc dầu thực vật) và 2 - 2,5 mL dung dịch NaOH 40%.\nBước 2: Đun hỗn hợp sôi nhẹ và liên tục khuấy đều bằng đũa thuỷ tinh. Thỉnh thoảng thêm vài giọt nước cất để giữ cho thể tích của hỗn hợp không đổi.\nBước 3: Sau 8 - 10 phút, rót thêm vào hỗn hợp 4 - 5 mL dung dịch NaCl bão hòa nóng, khuấy nhẹ.\nPhát biểu nào sau đây sai?",
          "svgKey": "saponification_experiment",
