          "But-2-ene: 3CH₃–CH=CH–CH₃ + 2KMnO₄ + 4H₂O -> 3CH₃–CHOH–CHOH–CH₃ + 2MnO₂↓ + 2KOH. Diol có 2 nhóm OH bậc 2",
