      {
        "kind": "trick",
        "t": "Mẹo ghi nhớ",
        "b": "Phân biệt: thấy -COO- (muối Na/K của acid béo) => xà phòng; thấy NGUYÊN TỐ S trong -SO3Na hoặc -OSO3Na => chất giặt rửa tổng hợp.\nEster + NaOH theo tỉ lệ mol 1:2 => ester của phenol (thu 2 muối + H2O, không có alcohol).\nEster thủy phân cho aldehyde/ketone => gốc alcohol dạng vinyl (-O-CH=CH2).\nCùng M: nhiệt độ sôi ester < alcohol < acid.\nBài toán chất béo: n(glycerol) = n(chất béo) = n(kiềm)/3 = n(muối)/3; bảo toàn khối lượng: m chất béo + m kiềm = m muối + m glycerol (NaOH M = 40, KOH M = 56).\nSố mol H2 cộng = (tổng số C=C trong các gốc acid) x n(chất béo)."
      },
      {
        "kind": "danger",
        "t": "Lỗi học sinh hay gặp",
        "b": "(1) Xà phòng là muối của ACID BÉO (mạch dài), không phải mọi muối của acid hữu cơ - CH3COONa không phải xà phòng.\n(2) Thủy phân trong ACID là thuận nghịch, trong KIỀM là một chiều; đọc kỹ để không trả lời ngược.\n(3) Câu có chữ \"đều\": \"các triglyceride đều cộng H2\" là SAI vì chất béo no không cộng.\n(4) Đếm liên kết π quên nhóm C=O: methyl methacrylate có 2π (1 C=C + 1 C=O).\n(5) Dùng bát/xoong nhôm đun chất béo với NaOH: kiềm ăn mòn nhôm (2Al + 2NaOH + 2H2O -> 2NaAlO2 + 3H2).\n(6) Tẩy rửa là nhũ hóa vật lí, không phải phản ứng hóa học với vết bẩn.\n(7) Nhầm acid béo: palmitic 16C (C15H31COOH), stearic 18C (C17H35COOH)."
      }
