        "text": "• Phương trình hoá học:\n  C₆H₅NH₂ + 3Br₂ → C₆H₂Br₃NH₂↓ (trắng) + 3HBr\n• Hiện tượng: Dung dịch bromine mất màu nâu đỏ và xuất hiện kết tủa trắng.\n• Ứng dụng: Dùng để nhận biết aniline hoặc định lượng aniline trong mẫu phân tích.",
