        "text": "• Với amine bậc 1 no (alkylamine): Sinh ra alcohol và giải phóng khí N₂:\n  C₂H₅NH₂ + HNO₂ → C₂H₅OH + N₂↑ + H₂O\n• Với aniline ở nhiệt độ thấp (0 - 5°C):\n  C₆H₅NH₂ + HNO₂ + HCl (0-5°C) → [C₆H₅-N≡N]⁺Cl⁻ + 2H₂O\n  (Muối benzenediazonium chloride).",
